#!/usr/bin/env python3
"""
Meridian WMS - offline batch load, SQL Server -> PostgreSQL (COPY protocol).

Prerequisites
  * Target schema already created (dotnet ef database update) and EMPTY.
  * Source is write-frozen (app in maintenance mode) - this is a consistent-cut load.
Behaviour
  * Loads parents before children, inside ONE PostgreSQL transaction (all-or-nothing).
  * Preserves legacy primary keys (identity columns are GENERATED BY DEFAULT).
  * Converts legacy DATETIME wall-clock values (written with DateTime.Now) to timestamptz
    using SOURCE_TZ; counts DST-ambiguous values so they can be reviewed.
  * Rejects NUL characters (PostgreSQL text cannot store U+0000) instead of silently altering data.
  * Resets every identity sequence to MAX(pk) so new inserts never collide.
Environment (secrets never on argv):  MSSQL_CONN, PG_CONN, SOURCE_TZ (required), CHUNK (default 10000)
"""
import datetime
import os
import sys
from zoneinfo import ZoneInfo

import psycopg
import pyodbc

# (table, pk, ordered columns, datetime columns). Parents first.
PLAN = [
    ("Warehouse", "WarehouseId", ["WarehouseId", "Code", "Name", "City", "Country"], []),
    ("Product", "ProductId", ["ProductId", "Sku", "Name", "Category", "UnitWeightKg",
                              "UnitPrice", "IsActive"], []),
    ("Order", "OrderId", ["OrderId", "OrderNumber", "CustomerName", "DestinationCity",
                          "DestinationCountry", "Status", "CreatedUtc"], ["CreatedUtc"]),
    ("InventoryItem", "InventoryItemId", ["InventoryItemId", "ProductId", "WarehouseId",
                                          "QuantityOnHand", "QuantityReserved", "BinLocation"], []),
    ("OrderLine", "OrderLineId", ["OrderLineId", "OrderId", "ProductId", "Quantity",
                                  "UnitPriceAtOrder"], []),
    ("Shipment", "ShipmentId", ["ShipmentId", "OrderId", "Carrier", "TrackingNumber",
                                "FromWarehouseCode", "ShippedUtc", "TotalWeightKg"], ["ShippedUtc"]),
]


def localize(naive, tz, stats):
    """Naive legacy wall-clock -> aware datetime in tz. Counts DST edge cases."""
    first = naive.replace(tzinfo=tz, fold=0)
    second = naive.replace(tzinfo=tz, fold=1)
    if first.utcoffset() != second.utcoffset():
        stats["dst_edge"] += 1  # ambiguous (autumn) or non-existent (spring) wall-clock time
    return first


def main():
    ms_conn, pg_conn = os.environ.get("MSSQL_CONN"), os.environ.get("PG_CONN")
    tz_name = os.environ.get("SOURCE_TZ")
    if not (ms_conn and pg_conn and tz_name):
        print("MSSQL_CONN, PG_CONN and SOURCE_TZ must be set in the environment", file=sys.stderr)
        return 2
    tz, chunk = ZoneInfo(tz_name), int(os.environ.get("CHUNK", "10000"))
    stats = {"dst_edge": 0}

    with pyodbc.connect(ms_conn, timeout=30, readonly=True) as mc, \
            psycopg.connect(pg_conn, connect_timeout=30) as pc:
        ms = mc.cursor()
        with pc.cursor() as pg:
            for table, _, _, _ in PLAN:
                pg.execute(f'SELECT EXISTS (SELECT 1 FROM public."{table}")')
                if pg.fetchone()[0]:
                    print(f'Target table "{table}" is not empty - aborting.', file=sys.stderr)
                    return 2

            for table, pk, cols, dt_cols in PLAN:
                ms.execute(f"SELECT {', '.join(f'[{c}]' for c in cols)} "
                           f"FROM dbo.[{table}] ORDER BY [{pk}]")
                dt_idx = {cols.index(c) for c in dt_cols}
                total = 0
                col_sql = ", ".join(f'"{c}"' for c in cols)
                with pg.copy(f'COPY public."{table}" ({col_sql}) FROM STDIN') as cp:
                    while True:
                        rows = ms.fetchmany(chunk)
                        if not rows:
                            break
                        for row in rows:
                            out = []
                            for i, v in enumerate(row):
                                if isinstance(v, str) and "\x00" in v:
                                    raise ValueError(f"NUL char in {table}.{cols[i]} where {pk}={row[0]}")
                                if i in dt_idx and isinstance(v, datetime.datetime):
                                    v = localize(v, tz, stats)
                                out.append(v)
                            cp.write_row(out)
                        total += len(rows)
                print(f"[{table}] loaded {total} rows")

            for table, pk, _, _ in PLAN:
                pg.execute(
                    f"SELECT setval(pg_get_serial_sequence('public.\"{table}\"', '{pk}'), "
                    f'COALESCE(MAX("{pk}"), 1), MAX("{pk}") IS NOT NULL) FROM public."{table}"')
            pc.commit()  # single commit: all tables or none

    print(f"Done. DST-ambiguous/non-existent timestamps needing review: {stats['dst_edge']}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
